<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
function require_admin_page(): array {
  $u=current_user();if(!$u){header('Location: /admin/login.php');exit;}if($u['role']!=='admin'){http_response_code(403);exit('Administrator access required.');}return $u;
}
function admin_header(string $active,string $title): void {
  $user=require_admin_page();header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store, private');
  echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.htmlspecialchars($title,ENT_QUOTES).' · TDC Tech Admin</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{--bg:#09090b;--panel:#12121a;--card:#171720;--border:#ffffff14;--text:#f4f4f5;--sub:#a1a1aa;--muted:#71717a;--indigo:#6366f1;--cyan:#22d3ee}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.shell{max-width:1480px;margin:auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:24px}.brand h1{font-size:1.35rem;margin:0 0 4px}.brand p{color:var(--sub);margin:0}.nav{display:flex;gap:8px;flex-wrap:wrap}.nav a,.btn,.tab{border:1px solid var(--border);border-radius:9px;background:#ffffff08;color:var(--text);padding:10px 13px;cursor:pointer;font:600 .82rem Inter;text-decoration:none}.nav a.active,.tab.active{background:#6366f133;border-color:#6366f177;color:#c7d2fe}.nav a:hover,.btn:hover{border-color:#6366f177}.btn.primary{background:var(--indigo);border-color:var(--indigo)}.btn.danger{color:#fca5a5}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;margin:18px 0}.stat,.panel,.card{background:var(--panel);border:1px solid var(--border);border-radius:14px;padding:16px}.stat span{color:var(--muted);font-size:.76rem}.stat strong{display:block;font-size:1.5rem;margin-top:8px}.panel{margin:14px 0}.panel h2{font-size:1.05rem;margin:0 0 14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.service-card{display:flex;align-items:center;gap:13px;text-decoration:none;color:inherit;background:var(--card);border:1px solid var(--border);border-radius:12px;padding:15px}.service-card:hover{border-color:#6366f188}.service-icon{font-size:1.5rem}.service-card strong{display:block}.service-card small,.muted{color:var(--sub)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:700px}th,td{padding:10px;text-align:left;border-bottom:1px solid var(--border);vertical-align:top}th{color:var(--muted);font-size:.71rem;text-transform:uppercase;letter-spacing:.04em}td{font-size:.83rem}.badge{padding:4px 8px;border-radius:99px;background:#6366f122;color:#c7d2fe;font-size:.72rem}.row-actions{display:flex;gap:6px;flex-wrap:wrap}.small{font-size:.75rem;padding:7px 9px}.input,select,textarea{width:100%;padding:10px;background:#09090b;border:1px solid var(--border);border-radius:7px;color:white;font:inherit}.input.short{width:110px}.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.field label{display:block;color:var(--sub);font-size:.76rem;margin-bottom:5px}.notice{min-height:22px;color:#86efac;padding:5px 0}.error{color:#fca5a5}.empty{color:var(--muted);padding:22px 0}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.chart{width:100%;height:220px;background:#09090b;border:1px solid var(--border);border-radius:10px;padding:12px}.split{display:grid;grid-template-columns:1.5fr 1fr;gap:14px}.hidden{display:none!important}@media(max-width:800px){.shell{padding:14px}.top{align-items:flex-start;flex-direction:column}.split{grid-template-columns:1fr}table{min-width:620px}}</style></head><body><main class="shell"><header class="top"><div class="brand"><h1>TDC Tech · Admin</h1><p>'.htmlspecialchars($title,ENT_QUOTES).' · Signed in as '.htmlspecialchars((string)$user['name'],ENT_QUOTES).'</p></div><nav class="nav"><a class="'.($active==='overview'?'active':'').'" href="/admin/">Overview</a><a class="'.($active==='content'?'active':'').'" href="/admin/content.php">Website content</a><a class="'.($active==='emails'?'active':'').'" href="/admin/emails.php">Email notifications</a><button class="btn" id="admin-logout" type="button">Sign out</button></nav></header><div class="notice" id="notice" role="status"></div><script>document.getElementById("admin-logout").addEventListener("click",async()=>{const c=await fetch("/api/csrf.php",{credentials:"same-origin"}).then(r=>r.json());await fetch("/api/auth.php",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":c.csrf},body:JSON.stringify({action:"logout"})});location.href="/admin/login.php";});</script>';
}
function admin_footer(): void {echo '</main></body></html>';}
